#!/usr/bin/env python3
"""Ingest pets from the tools API → util/autogenerated/pets.py.

Pet detail includes id/name/desc, egg{name,desc,sprite,sheet},
looks[], rareLooks[], xpRequirements[], levels[{level, xp, attributes[]}],
hatchingRequirements (nullable: null means no hatching gate at all,
distinct from empty list).
"""
from __future__ import annotations
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent.parent))
from util.scrapers.tools_api_client import ToolsAPIClient  # noqa: E402
from util.scrapers.tools_api_dump import dump_endpoint  # noqa: E402


def run(client: ToolsAPIClient, *, use_cache: bool = True) -> int:
    out = (
        Path(__file__).resolve().parent.parent
        / 'autogenerated' / 'pets.py'
    )
    n = dump_endpoint(
        client, 'pets', str(out), 'PETS',
        use_cache=use_cache,
        docstring=(
            'Pets — keyed by pet id. hatchingRequirements is nullable: '
            'None means no hatching condition (distinct from empty list).'
        ),
    )
    print(f'  [pets               ] {n:4d} entities → pets.py')
    return n


if __name__ == '__main__':
    raise SystemExit(0 if run(ToolsAPIClient()) else 1)
